#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]; KIT=ROOT/'catalog/kits/telecom-infrastructure'; B=Path(__file__).resolve().parent
idx=json.loads((ROOT/'catalog/index.json').read_text()); rows=[a for a in idx['assets'] if a['kit']=='telecom-infrastructure']; audit=json.loads((B/'asset-check-results.json').read_text())
lines=['# Telecom infrastructure kit','','Fifty-six original low-poly communications-site, rooftop, radio and fiber-network props. All sources use millimetres, Z up, base origin at z = 0 and editable `scale` and `color` controls. Audited exports range from %d to %d triangles, use one material and remain within their per-asset budgets.'%tuple(audit['triangleRange']),'','The [telecom infrastructure wave demo bundle](../../../artifacts/catalog-demos/telecom-infrastructure-wave-20261102/README.md) retains the generator, local audit evidence, rendered previews, page check, capture settings and visually inspected MP4. Local page generation was checked; deployed behavior remains unverified.','','| id | asset | description | knobs | triangles |','| --- | --- | --- | --- | ---: |']
for a in rows: lines.append(f"| `{a['id']}` | {a['title']} | {a['description']} | {' · '.join(p['name'] for p in a['params'])} | {a['stats']['triangles']} |")
lines += ['', '## Rebuild and verify','','```sh','python3 artifacts/catalog-demos/telecom-infrastructure-wave-20261102/generate_telecom_assets.py','npx tsx scripts/buildAssetCatalog.ts','npx eslint catalog/','npx vitest run tests/integration/catalog/','python3 artifacts/catalog-demos/telecom-infrastructure-wave-20261102/render_telecom_previews.py','npx tsx scripts/buildCatalogPages.ts /tmp/kernelcad-telecom-pages','python3 artifacts/catalog-demos/telecom-infrastructure-wave-20261102/verify_telecom_pages.py /tmp/kernelcad-telecom-pages','```','','## License and scope','','Every asset is dedicated to the public domain under [CC0 1.0](https://creativecommons.org/publicdomain/zero/1.0/). These are stylized scene props; they do not claim RF performance, wind loading, weatherproofing, installation suitability, regulatory compliance or physical acceptance.','','See the demo README for current public-site status and verification limits.']
(KIT/'README.md').write_text('\n'.join(lines)+'\n');print('wrote README')
